import java.lang.ref.*;

public class Main {
    public static void main(String[] args) {
        System.out.println("=== reference class hierarchy (Reference -> subclass) ===");
        for (Class<?> c : new Class<?>[]{Strongish.class, SoftReference.class, WeakReference.class, PhantomReference.class}) {
            StringBuilder chain = new StringBuilder(c.getSimpleName());
            for (Class<?> s = c.getSuperclass(); s != null && s != Object.class; s = s.getSuperclass())
                chain.append(" -> ").append(s.getSimpleName());
            System.out.println("    " + chain);
        }

        System.out.println("=== reaching states WITHOUT triggering GC ===");
        Object strong = new Object();
        ReferenceQueue<Object> q = new ReferenceQueue<>();
        SoftReference<Object> soft = new SoftReference<>(strong);
        WeakReference<Object> weak = new WeakReference<>(strong);
        PhantomReference<Object> phantom = new PhantomReference<>(strong, q);

        System.out.println("    strong reference alive            : " + (strong != null));
        System.out.println("    soft.get() != null (no pressure)  : " + (soft.get() != null));
        System.out.println("    weak.get() != null (no GC yet)    : " + (weak.get() != null));
        System.out.println("    phantom.get() == null (spec)      : " + (phantom.get() == null));
        System.out.println("    soft is enqueued now              : " + soft.isEnqueued());
        System.out.println("    phantom is enqueued now           : " + phantom.isEnqueued());

        System.out.println("=== reachability classification (pure model, deterministic) ===");
        System.out.println("    strongly reachable -> never collected");
        System.out.println("    softly  reachable -> collected only under memory pressure");
        System.out.println("    weakly  reachable -> collected at the next GC");
        System.out.println("    phantom reachable -> already finalized, queue used as death notice");
        System.out.println("ThreadLocal leak root cause: key is weak (collected),"
                + " value is strongly held by the Entry -> value leaks until remove()");
    }

    /** 不是 Reference 的子类，只用来对比「强引用」不是一种类 */
    static final class Strongish { }
}
